code.en:
flowchart LR
  D["current draft"] --> CR["critique"] --> RV["revise"] --> SC{"score(new) >= score(old)?"}
  SC -->|"yes: accept"| ST{"stop rule?<br/>max_iters, target,<br/>critique ok, patience"}
  SC -->|"no: keep old"| ST
  ST -->|"no"| D
  ST -->|"yes"| F["final answer"]

