flowchart LR
  D["brouillon courant"] --> CR["critique"] --> RV["réviser"] --> SC{"score(nouveau) >= score(ancien) ?"}
  SC -->|"oui : accepter"| ST{"règle d'arrêt ?<br/>max_iters, cible,<br/>critique ok, patience"}
  SC -->|"non : garder l'ancien"| ST
  ST -->|"non"| D
  ST -->|"oui"| F["réponse finale"]
